package in.smkt.haldesk;
import android.content.Context;import org.json.JSONObject;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk={26,35},manifest=Config.NONE)
public class BookStoreTest{
 private Context context;private String empty="{\"version\":4,\"legs\":[],\"journal\":[]}";
 @Before public void setup(){context=RuntimeEnvironment.getApplication();context.deleteDatabase("haldesk_book.db");}
 @Test public void survivesRestartAndRetainsPrevious()throws Exception{BookStore s=new BookStore(context);assertTrue(s.load(false).isNull("book"));assertEquals(1,s.save(empty,0).getLong("revision"));assertEquals(2,s.save(empty,1).getLong("revision"));s.close();s=new BookStore(context);assertEquals(2,s.load(false).getLong("revision"));assertEquals(1,s.load(true).getLong("revision"));s.close();}
 @Test public void invalidWritesDoNotEraseBook()throws Exception{BookStore s=new BookStore(context);s.save(empty,0);try{s.save(empty,0);fail();}catch(Exception e){assertEquals("revision_conflict_reload_required",e.getMessage());}try{s.save("invalid",1);fail();}catch(Exception e){}assertEquals(1,s.load(false).getLong("revision"));s.close();}
 @Test public void cacheDoesNotBecomeLive()throws Exception{BookStore s=new BookStore(context);s.cachePut("snapshot","{\"asOf\":\"2026-01-01T10:00:00Z\"}");JSONObject c=s.cacheGet("snapshot");assertTrue(c.getBoolean("cached"));assertEquals("2026-01-01T10:00:00Z",c.getJSONObject("data").getString("asOf"));try{s.cachePut("snapshot","{\"token\":\"synthetic\"}");fail();}catch(Exception e){assertEquals("credentials_forbidden_in_backup",e.getMessage());}s.close();}

 @Test public void recoveryRejectsUnreviewedNewerRevision()throws Exception{BookStore store=new BookStore(context);try{store.save(empty,0);store.save(empty,1);long reviewed=2;store.save(empty,2);try{store.restorePrevious(reviewed);fail("overwrote newer revision");}catch(Exception error){assertEquals("revision_conflict_reload_required",error.getMessage());}assertEquals(3,store.currentRevision());}finally{store.close();}}
 @Test public void corruptCurrentBookRecoversWithoutDestroyingEvidence()throws Exception{BookStore store=new BookStore(context);try{String confirmed=new JSONObject(empty).put("riskProfile",new JSONObject().put("confirmedAt","2026-11-01T06:00:00Z").put("confirmedBook","rev-synthetic")).toString();store.save(confirmed,0);store.save(empty,1);store.getWritableDatabase().execSQL("UPDATE book SET payload='corrupted bytes' WHERE id=1");try{store.load(false);fail("corrupt book accepted");}catch(Exception error){assertEquals("book_corrupted_recovery_available",error.getMessage());}JSONObject restored=store.restorePrevious(2);assertEquals(3,restored.getLong("revision"));assertTrue(restored.getJSONObject("book").getJSONObject("riskProfile").isNull("confirmedAt"));assertTrue(restored.getJSONObject("book").getJSONObject("riskProfile").isNull("confirmedBook"));try(android.database.Cursor cursor=store.getReadableDatabase().rawQuery("SELECT payload FROM quarantine",null)){assertTrue(cursor.moveToFirst());assertEquals("corrupted bytes",cursor.getString(0));}assertEquals(3,store.load(false).getLong("revision"));}finally{store.close();}}
}